//! Rust host bindings with the Web DOM backend running in a WebView.
//!
//! The whole import closure becomes one Rust source file, included by the
//! host through `weft_ui::include_weft!`. It declares plain model structs,
//! change-tracking `XxxMut` accessors handed to event handlers, event structs
//! in an `events` module, and one root component type per component. The view
//! modules generated by the Web backend are embedded as strings and served to
//! the WebView by the `weft_ui` runtime.

use std::fmt::Write;

use crate::ir::{Component, ComponentId, Event, Model, ModelId, ParamKind, Program, Type};
use crate::loader;

use super::web::{self, WebOptions};

/// URL path under which the `weft_ui` runtime serves the JS runtime module.
const RUNTIME_URL: &str = "/__weft/index.js";

/// Path of the runtime support module inside the generated code.
const RT: &str = "__w";

/// Generates the Rust host module for the program's import closure.
#[must_use]
pub fn generate(program: &Program) -> String {
    let mut out = String::new();
    let entry = module_path(program, program.entry);
    w(
        &mut out,
        format_args!("// @generated by weft-ui-compiler from `{entry}`. Do not edit.\n"),
    );
    w(
        &mut out,
        format_args!(
            "#[allow(unused, non_camel_case_types, non_snake_case, clippy::all, clippy::pedantic)]\nmod __weft {{\n    use ::weft_ui::__private as {RT};\n"
        ),
    );
    for model in &program.models {
        model_items(program, model, &mut out);
    }
    if !program.events.is_empty() {
        out.push_str("\n    /// Events the view sends to the host.\n    pub mod events {\n");
        w(
            &mut out,
            format_args!("        use ::weft_ui::__private as {RT};\n"),
        );
        for event in &program.events {
            event_items(program, event, &mut out);
        }
        out.push_str("    }\n");
    }
    for (index, component) in program.components.iter().enumerate() {
        component_items(program, ComponentId(offset(index)), component, &mut out);
    }
    view_items(program, &mut out);
    out.push_str("}\n\n");

    let mut exports: Vec<String> = Vec::new();
    for model in &program.models {
        exports.push(type_ident(&model.name));
        exports.push(mut_ident(&model.name));
    }
    if !program.events.is_empty() {
        exports.push("events".to_owned());
    }
    exports.extend(program.components.iter().map(|c| type_ident(&c.name)));
    w(
        &mut out,
        format_args!("pub use __weft::{{{}}};\n", exports.join(", ")),
    );
    out
}

/// Appends formatted text; writing into a `String` cannot fail.
fn w(out: &mut String, args: std::fmt::Arguments<'_>) {
    out.write_fmt(args)
        .expect("formatting into a String never fails");
}

fn offset(index: usize) -> u32 {
    crate::span::offset(index)
}

fn module_path(program: &Program, file: crate::span::FileId) -> &str {
    program
        .modules
        .iter()
        .find(|m| m.file == file)
        .map_or("", |m| m.path.as_str())
}

/// URL path of a module in the WebView. Leading `..` segments are dropped,
/// exactly as URL resolution of the generated relative imports does.
fn module_url(path: &str) -> String {
    loader::normalize(&format!("/{path}"))
}

/* ---- names ---------------------------------------------------------------- */

/// Rust keywords that need a raw identifier.
const KEYWORDS: &[&str] = &[
    "abstract", "as", "async", "await", "become", "box", "break", "const", "continue", "do", "dyn",
    "else", "enum", "extern", "false", "final", "fn", "for", "gen", "if", "impl", "in", "let",
    "loop", "macro", "match", "mod", "move", "mut", "override", "priv", "pub", "ref", "return",
    "static", "struct", "trait", "true", "try", "type", "typeof", "unsafe", "unsized", "use",
    "virtual", "where", "while", "yield",
];

/// A DSL identifier as a Rust identifier for values, fields and modules.
fn ident(name: &str) -> String {
    match name {
        // Keywords that cannot be raw identifiers.
        "self" | "Self" | "super" | "crate" | "_" => format!("{name}_"),
        _ if KEYWORDS.contains(&name) => format!("r#{name}"),
        _ => name.to_owned(),
    }
}

/// A declaration name as a Rust type name.
fn type_ident(name: &str) -> String {
    ident(name)
}

/// Name of the change-tracking accessor type of a model.
fn mut_ident(model: &str) -> String {
    format!("{model}Mut")
}

/// Rust string literal.
fn literal(value: &str) -> String {
    format!("{value:?}")
}

/// `TextChanged` → `text_changed`.
fn snake_case(name: &str) -> String {
    let chars: Vec<char> = name.chars().collect();
    let mut out = String::with_capacity(name.len() + 4);
    for (i, &c) in chars.iter().enumerate() {
        if c.is_uppercase() {
            let prev = i.checked_sub(1).map(|p| chars[p]);
            let next = chars.get(i + 1);
            let boundary = prev.is_some_and(|p| p.is_lowercase() || p.is_ascii_digit())
                || (prev.is_some_and(char::is_uppercase) && next.is_some_and(|n| n.is_lowercase()));
            if boundary && !out.ends_with('_') {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// Rust type of a DSL type; `models` prefixes model names (`super::` inside
/// the `events` module).
fn rust_type(program: &Program, ty: &Type, models: &str) -> String {
    match ty {
        Type::Int => "i64".to_owned(),
        Type::Float => "f64".to_owned(),
        Type::Bool => "bool".to_owned(),
        Type::String => "::std::string::String".to_owned(),
        Type::Model(id) => format!("{models}{}", type_ident(&program.model(*id).name)),
        Type::Array(elem) => format!("::std::vec::Vec<{}>", rust_type(program, elem, models)),
        Type::Optional(inner) => {
            format!(
                "::std::option::Option<{}>",
                rust_type(program, inner, models)
            )
        }
        Type::Null | Type::Error => unreachable!("not a declared type"),
    }
}

/* ---- models ----------------------------------------------------------------- */

fn model_items(program: &Program, model: &Model, out: &mut String) {
    let name = type_ident(&model.name);
    let tracked = mut_ident(&model.name);
    let source = module_path(program, model.file);

    w(
        out,
        format_args!(
            "\n    /// Model `{}` declared in `{source}`.\n    #[derive(Debug, Clone, PartialEq, Default)]\n    pub struct {name} {{\n",
            model.name
        ),
    );
    for field in &model.fields {
        w(
            out,
            format_args!(
                "        pub {}: {},\n",
                ident(&field.name),
                rust_type(program, &field.ty, "")
            ),
        );
    }
    out.push_str("    }\n");

    w(
        out,
        format_args!(
            "
    /// Change-tracking access to a [`{name}`] inside event handlers.
    ///
    /// Fields are read through `Deref`; setters and `_mut` accessors record
    /// the change so the view is patched at the next flush.
    pub struct {tracked}<'a> {{
        model: &'a mut {name},
        changes: {RT}::Changes<'a>,
    }}

    impl ::std::ops::Deref for {tracked}<'_> {{
        type Target = {name};

        fn deref(&self) -> &{name} {{
            self.model
        }}
    }}

    impl {tracked}<'_> {{
"
        ),
    );
    for field in &model.fields {
        let field_ident = ident(&field.name);
        let method = &field.name;
        let key = literal(&field.name);
        let ty = rust_type(program, &field.ty, "");
        w(
            out,
            format_args!(
                "        /// Sets `{0}`, recording a change only when the value differs.
        pub fn set_{method}(&mut self, value: {ty}) {{
            if self.model.{field_ident} != value {{
                self.model.{field_ident} = value;
                self.changes.mark({key});
            }}
        }}
",
                field.name
            ),
        );
        if let Type::Model(nested) = &field.ty {
            w(
                out,
                format_args!(
                    "        /// Change-tracking access to the nested `{0}` model.
        pub fn {method}_mut(&mut self) -> {1}<'_> {{
            {RT}::Model::track(&mut self.model.{field_ident}, self.changes.field({key}))
        }}
",
                    field.name,
                    mut_ident(&program.model(*nested).name)
                ),
            );
        } else {
            w(
                out,
                format_args!(
                    "        /// Mutable access to `{0}`; always records a change.
        pub fn {method}_mut(&mut self) -> &mut {ty} {{
            self.changes.mark({key});
            &mut self.model.{field_ident}
        }}
",
                    field.name
                ),
            );
        }
    }
    out.push_str("    }\n");

    // JSON conversions.
    let entries: Vec<String> = model
        .fields
        .iter()
        .map(|f| {
            format!(
                "({}, {RT}::ToJson::to_json(&self.{}))",
                literal(&f.name),
                ident(&f.name)
            )
        })
        .collect();
    let decoded: Vec<String> = model
        .fields
        .iter()
        .map(|f| format!("{}: fields.get({})?", ident(&f.name), literal(&f.name)))
        .collect();
    w(
        out,
        format_args!(
            "
    impl {RT}::ToJson for {name} {{
        fn to_json(&self) -> {RT}::Value {{
            {RT}::object([{entries}])
        }}
    }}

    impl {RT}::FromJson for {name} {{
        fn from_json(value: &{RT}::Value) -> ::std::result::Result<Self, {RT}::DecodeError> {{
            let fields = {RT}::Fields::new(value, {model_name})?;
            ::std::result::Result::Ok(Self {{ {decoded} }})
        }}
    }}

    impl {RT}::Model for {name} {{
        type Mut<'a> = {tracked}<'a>;

        fn track<'a>(&'a mut self, changes: {RT}::Changes<'a>) -> {tracked}<'a> {{
            {tracked} {{ model: self, changes }}
        }}

        fn path_json(&self, path: &[&'static str]) -> {RT}::Value {{
            match path {{
                [] => {RT}::ToJson::to_json(self),
",
            entries = entries.join(", "),
            decoded = decoded.join(", "),
            model_name = literal(&model.name),
        ),
    );
    for field in &model.fields {
        let key = literal(&field.name);
        let field_ident = ident(&field.name);
        if matches!(field.ty, Type::Model(_)) {
            w(
                out,
                format_args!(
                    "                [{key}, rest @ ..] => {RT}::Model::path_json(&self.{field_ident}, rest),\n"
                ),
            );
        } else {
            w(
                out,
                format_args!(
                    "                [{key}] => {RT}::ToJson::to_json(&self.{field_ident}),\n"
                ),
            );
        }
    }
    w(
        out,
        format_args!(
            "                _ => {RT}::unknown_path({}, path),\n            }}\n        }}\n    }}\n",
            literal(&model.name)
        ),
    );
}

/* ---- events ----------------------------------------------------------------- */

fn event_items(program: &Program, event: &Event, out: &mut String) {
    let name = type_ident(&event.name);
    let source = module_path(program, event.file);
    w(
        out,
        format_args!(
            "\n        /// Event `{}` declared in `{source}`.\n",
            event.name
        ),
    );
    if event.params.is_empty() {
        w(
            out,
            format_args!(
                "        #[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
        pub struct {name};

        impl {RT}::FromJson for {name} {{
            fn from_json(_: &{RT}::Value) -> ::std::result::Result<Self, {RT}::DecodeError> {{
                ::std::result::Result::Ok(Self)
            }}
        }}
"
            ),
        );
        return;
    }
    w(
        out,
        format_args!("        #[derive(Debug, Clone, PartialEq)]\n        pub struct {name} {{\n"),
    );
    for param in &event.params {
        w(
            out,
            format_args!(
                "            pub {}: {},\n",
                ident(&param.name),
                rust_type(program, &param.ty, "super::")
            ),
        );
    }
    let decoded: Vec<String> = event
        .params
        .iter()
        .map(|p| format!("{}: fields.get({})?", ident(&p.name), literal(&p.name)))
        .collect();
    w(
        out,
        format_args!(
            "        }}

        impl {RT}::FromJson for {name} {{
            fn from_json(value: &{RT}::Value) -> ::std::result::Result<Self, {RT}::DecodeError> {{
                let fields = {RT}::Fields::new(value, {event_name})?;
                ::std::result::Result::Ok(Self {{ {decoded} }})
            }}
        }}
",
            event_name = literal(&event.name),
            decoded = decoded.join(", "),
        ),
    );
}

/* ---- components ------------------------------------------------------------- */

/// The model handlers receive: the first parameter when it is a model.
fn handler_model(component: &Component) -> Option<ModelId> {
    match component.params.first().map(|p| &p.kind) {
        Some(ParamKind::Value(Type::Model(id))) => Some(*id),
        _ => None,
    }
}

fn view_static(id: ComponentId) -> String {
    format!("__VIEW_{}", id.0)
}

fn component_items(program: &Program, id: ComponentId, component: &Component, out: &mut String) {
    let name = type_ident(&component.name);
    let source = module_path(program, component.file);
    let model = handler_model(component);
    let (model_type, tracked) = match model {
        Some(m) => {
            let model_name = &program.model(m).name;
            (
                type_ident(model_name),
                format!("{}<'_>", mut_ident(model_name)),
            )
        }
        None => ("()".to_owned(), "()".to_owned()),
    };

    let mut params = Vec::new();
    let mut rest = Vec::new();
    for (index, param) in component.params.iter().enumerate() {
        let ParamKind::Value(ty) = &param.kind else {
            continue;
        };
        let param_ident = ident(&param.name);
        params.push(format!("{param_ident}: {}", rust_type(program, ty, "")));
        if !(index == 0 && model.is_some()) {
            rest.push(format!("{RT}::ToJson::to_json(&{param_ident})"));
        }
    }
    let host = match model {
        Some(_) => format!(
            "{RT}::Host::new(&{}, {}, ::std::vec![{}])",
            view_static(id),
            ident(&component.params[0].name),
            rest.join(", ")
        ),
        None => format!(
            "{RT}::Host::fixed(&{}, ::std::vec![{}])",
            view_static(id),
            rest.join(", ")
        ),
    };
    let model_doc = match model {
        Some(_) => format!(
            "Handlers receive change-tracking access to the `{}` argument.",
            component.params[0].name
        ),
        None => "The first parameter is not a model, so handlers receive `&mut ()`.".to_owned(),
    };

    w(
        out,
        format_args!(
            "
    /// Root component `{cname}` declared in `{source}`.
    ///
    /// Owns its arguments and receives every event of its view, including
    /// those emitted by nested components. {model_doc}
    pub struct {name} {{
        host: {RT}::Host<{model_type}>,
    }}

    impl {name} {{
        /// Creates the component; arguments follow the declared parameters.
        pub fn new({params}) -> Self {{
            Self {{ host: {host} }}
        }}
",
            cname = component.name,
            params = params.join(", "),
        ),
    );
    for &event in &component.reachable_events {
        let event = program.event(event);
        let event_type = format!("events::{}", type_ident(&event.name));
        let method = format!("on_{}", snake_case(&event.name));
        let key = literal(&event.name);
        w(
            out,
            format_args!(
                "
        /// Registers a handler for [`{event_type}`].
        pub fn {method}(
            &self,
            handler: impl ::std::ops::FnMut(&mut {tracked}, {event_type}) + 'static,
        ) {{
            self.host.on({key}, handler);
        }}

        /// Registers an asynchronous handler for [`{event_type}`]; it runs on
        /// the UI thread and changes the model through the handle.
        pub fn {method}_async<F, Fut>(&self, handler: F)
        where
            F: ::std::ops::FnMut(::weft_ui::ModelHandle<{model_type}>, {event_type}) -> Fut + 'static,
            Fut: ::std::future::Future<Output = ()> + 'static,
        {{
            self.host.on_async({key}, handler);
        }}
"
            ),
        );
    }
    w(
        out,
        format_args!(
            "    }}

    impl ::std::convert::From<{name}> for ::weft_ui::App {{
        fn from(component: {name}) -> Self {{
            component.host.into_app()
        }}
    }}
"
        ),
    );
}

/* ---- embedded view ---------------------------------------------------------- */

fn view_items(program: &Program, out: &mut String) {
    let options = WebOptions {
        runtime: RUNTIME_URL.to_owned(),
    };
    out.push_str(&format!("\n    static __MODULES: &[{RT}::Module] = &[\n"));
    for module in &program.modules {
        let js = web::generate_module(program, module.file, &options);
        w(
            out,
            format_args!(
                "        {RT}::Module {{ path: {}, code: {} }},\n",
                literal(&module_url(&module.path)),
                literal(&js.code)
            ),
        );
    }
    out.push_str("    ];\n");
    for (index, component) in program.components.iter().enumerate() {
        let id = ComponentId(offset(index));
        let events: Vec<String> = component
            .reachable_events
            .iter()
            .map(|&e| literal(&program.event(e).name))
            .collect();
        w(
            out,
            format_args!(
                "
    static {}: {RT}::View = {RT}::View {{
        title: {title},
        entry: {entry},
        export: {title},
        events: &[{events}],
        modules: __MODULES,
    }};
",
                view_static(id),
                title = literal(&component.name),
                entry = literal(&module_url(module_path(program, component.file))),
                events = events.join(", "),
            ),
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snake_case_splits_words_and_acronyms() {
        assert_eq!(snake_case("TextChanged"), "text_changed");
        assert_eq!(snake_case("Remove"), "remove");
        assert_eq!(snake_case("HTTPRequest"), "http_request");
        assert_eq!(snake_case("item2Shown"), "item2_shown");
        assert_eq!(snake_case("loaded"), "loaded");
    }

    #[test]
    fn identifiers_avoid_keywords() {
        assert_eq!(ident("type"), "r#type");
        assert_eq!(ident("self"), "self_");
        assert_eq!(ident("draft"), "draft");
    }

    #[test]
    fn module_urls_stay_under_the_root() {
        assert_eq!(module_url("ui/TodoList.weft"), "/ui/TodoList.weft");
        assert_eq!(module_url("../shared/m.weft"), "/shared/m.weft");
    }
}
